function readRawProfile(id){if(!$(`#${id}-name`))return{};const value=key=>$(`#${id}-${key}`)?.value||'';return{name:value('name'),date:value('date'),time:value('time'),gender:value('gender'),time_accuracy:value('time_accuracy'),place:value('place'),latitude:value('latitude'),longitude:value('longitude'),timezone:value('timezone'),region:value('region')||'IN'};}
