function renderWindowControls(previous=null){const old=previous||readWindowRaw();const box=$('#window-controls');box.replaceChildren(el('h3',{text:t('eventDetails')}),el('p',{text:t('eventDetailsHelp')}));const grid=el('div',{class:'window-form-grid'});const start=field('event-start','startDate','date',{required:true,value:old.start||today()});const defaultEnd=new Date();defaultEnd.setDate(defaultEnd.getDate()+90);const end=field('event-end','endDate','date',{required:true,value:old.end||`${defaultEnd.getFullYear()}-${String(defaultEnd.getMonth()+1).padStart(2,'0')}-${String(defaultEnd.getDate()).padStart(2,'0')}`});grid.append(start.wrap,end.wrap);grid.append(el('div',{class:'field span-2'},el('button',{type:'button',class:'small-button',onclick:useBirthplaceForEvent,text:t('useBirthplace')})));grid.append(buildPlaceSearch('event',old));box.append(grid);for(const input of $$('input,select',grid))input.addEventListener('input',invalidateResult);}
