async function api(path,options={}){let response;try{response=await fetch(path,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});}catch(_){throw new Error(t('networkError'));}let data;try{data=await response.json();}catch(_){throw new Error(t('apiError'));}if(!response.ok){let detail=data.detail||data.error;const original=typeof detail==='string'?detail:Array.isArray(detail)?detail.map(x=>`${(x.loc||[]).slice(1).join('.')}: ${x.msg}`).join('; '):'';const error=new Error(`${t('calculationError')} · ${localizeServerError(original,data)}`);error.serverDetail=original;throw error;}return data;}
function localizeServerError(original,data){
if(state.lang==='en')return original||t('apiError');
const messages=[
[/did not occur|clock moved forward/i,['The clock skipped this birth time. Correct the recorded time.','घड़ी परिवर्तन के कारण यह जन्म समय हुआ नहीं था। दर्ज समय सुधारें।','घड्याळबदलामुळे ही जन्मवेळ आली नव्हती. नोंदवलेली वेळ दुरुस्त करा.']],
[/occurred twice|unambiguous UTC/i,['This time occurred twice. Confirm its UTC offset and enter the matching UTC date and time.','यह समय दो बार हुआ था। सही UTC अंतर की पुष्टि करके संबंधित UTC तिथि व समय भरें।','ही वेळ दोनदा आली होती. योग्य UTC फरक तपासून संबंधित UTC तारीख व वेळ भरा.']],
[/IANA|timezone|time zone/i,['Enter a valid IANA timezone such as Asia/Kolkata.','सही IANA समय क्षेत्र भरें, जैसे Asia/Kolkata।','योग्य IANA वेळक्षेत्र भरा, उदा. Asia/Kolkata.']],
[/future|1900|birth date/i,['Enter a birth date from 1900 through today.','1900 से आज तक की जन्म तारीख भरें।','1900 पासून आजपर्यंतची जन्मतारीख भरा.']],
[/HH:MM|birth time|local time/i,['Enter the recorded birth time in 24-hour HH:MM format.','दर्ज जन्म समय 24-घंटे HH:MM प्रारूप में भरें।','नोंदवलेली जन्मवेळ 24 तासांच्या HH:MM स्वरूपात भरा.']],
[/latitude|longitude|coordinates/i,['Check the selected location and its latitude and longitude.','चुने स्थान तथा अक्षांश और देशांतर जाँचें।','निवडलेले ठिकाण व अक्षांश आणि रेखांश तपासा.']],
[/366/i,['Select a date range of no more than 366 days.','अधिकतम 366 दिनों की तिथि सीमा चुनें।','जास्तीत जास्त 366 दिवसांची तारीख मर्यादा निवडा.']],
[/ordered dates|2100/i,['Select ordered dates between 1900 and 2100.','1900–2100 के बीच क्रमबद्ध तिथियाँ चुनें।','1900–2100 दरम्यान क्रमवार तारखा निवडा.']],
[/ephemeris|fallback|data file|Swiss/i,['Required ephemeris data is unavailable. Restore the data/ephe folder from the ZIP.','आवश्यक एफेमेरिस डेटा उपलब्ध नहीं है। ZIP से data/ephe फ़ोल्डर बहाल करें।','आवश्यक एफेमेरिस माहिती उपलब्ध नाही. ZIP मधून data/ephe फोल्डर पुनर्स्थापित करा.']],
[/name|1–100/i,['Enter a name of 1–100 characters.','1–100 अक्षरों का नाम भरें।','1–100 अक्षरांचे नाव भरा.']],
[/saved profile not found/i,['This saved profile was not found. Refresh the saved list.','सहेजा विवरण नहीं मिला। सहेजी सूची रीफ़्रेश करें।','जतन केलेला तपशील सापडला नाही. यादी पुन्हा उघडा.']],
[/local access|cross-origin/i,['Open the local application URL returned by the Python launcher.','Python लॉन्चर द्वारा दिया स्थानीय ऐप URL खोलें।','Python लाँचरने दिलेला स्थानिक अॅप URL उघडा.']],
[/time accuracy|exact or approximate/i,['Choose recorded or approximate birth time.','दर्ज या अनुमानित जन्म समय चुनें।','नोंदवलेली किंवा अंदाजे जन्मवेळ निवडा.']]
];
const match=messages.find(([pattern])=>pattern.test(original));if(match)return localized(match[1]);
if(data.fields?.length){const fieldNames={name:'fullName',date:'birthDate',time:'birthTime',gender:'gender',timezone:'timezone',latitude:'latitude',longitude:'longitude',place:'birthplace',time_accuracy:'timeAccuracy',start_date:'startDate',end_date:'endDate'};const labels=[...new Set(data.fields.map(item=>t(fieldNames[item.field.split('.').pop()]||'birthDetails')))];return `${t('apiError')} (${labels.join(', ')})`;}
return t('apiError');
}
