function hideNotification(){$('#notification').hidden=true;}
async function calculate(event){event.preventDefault();if(state.busy){notify(t('busyNotice'));return;}hideNotification();let payload;try{const a=getProfile('a'),review=readReviewRaw();if(!review.as_of||!Number.isInteger(Number(review.horizon_months))||Number(review.horizon_months)<1||Number(review.horizon_months)>60)throw new Error(t('reviewInputError'));if(review.as_of<a.date)throw new Error(t('reviewBeforeBirth'));payload={section:state.view,profile:a,as_of:review.as_of,horizon_months:Number(review.horizon_months),relationship_status:$('#relationship-status')?.value||'considering'};if(state.view==='compatibility')payload.person_b=getProfile('b');}catch(error){if(error.message!=='validation')notify(error.message,'error');return;}
const request=++state.requestSequence,view=state.view;state.busy=true;state.lastPayload=null;updateViewHeader();$('#results').replaceChildren(el('div',{class:'loading-panel'},el('span',{class:'spinner','aria-hidden':'true'}),el('p',{text:t('calculating')})));$('#empty-insight').hidden=true;try{const data=await api('/api/report',{method:'POST',body:JSON.stringify(payload)});if(request!==state.requestSequence||view!==state.view)return;if(!data||typeof data!=='object')throw new Error(t('resultUnavailable'));state.result=data;state.resultView=view;state.lastPayload=payload;state.periodIndex=0;state.monthIndex=0;renderResult();$('#results').scrollIntoView({behavior:'smooth',block:'start'});}catch(error){if(request!==state.requestSequence)return;$('#results').replaceChildren();$('#empty-insight').hidden=false;notify(error.message,'error');}finally{if(request===state.requestSequence){state.busy=false;updateViewHeader();}}}
