function localized(values){return values?.[['en','hi','mr'].indexOf(state.lang)]||values?.[0]||'—';}
function planetName(name){return planets[name]?localized(planets[name]):name||'—';}
function signName(index,name){const i=Number.isInteger(index)?index:signNames.en.indexOf(name);return signNames[state.lang][i]||name||'—';}
function starName(name){const index=nakshatraEn.indexOf(name);return state.lang==='en'||index<0?name||'—':nakshatraNative[index];}
function formatDate(value,includeTime=false){if(!value)return'—';try{const d=value.length===10?new Date(value+'T12:00:00Z'):new Date(value);if(Number.isNaN(d.getTime()))return String(value);return new Intl.DateTimeFormat(state.lang==='hi'?'hi-IN':state.lang==='mr'?'mr-IN':'en-GB',{day:'2-digit',month:'short',year:'numeric',...(includeTime?{hour:'2-digit',minute:'2-digit',hour12:false}:{}),timeZone:'UTC'}).format(d);}catch(_){return String(value);}}
function fixed(value,digits=2){return Number.isFinite(Number(value))?Number(value).toFixed(digits):'—';}
function scoreValue(value){return Number.isInteger(Number(value))?String(value):fixed(value,1);}
function fact(label,value){return el('div',{class:'fact'},el('small',{text:t(label)}),el('strong',{text:value??'—'}));}
function resultHeading(key){return el('div',{class:'result-heading'},el('div',{},el('h2',{text:t('reportReady')+' · '+t(state.resultView)}),el('p',{class:'result-meta',text:t('calculatedNow')})),el('div',{class:'result-actions report-actions'},el('button',{id:'download-pdf',type:'button',class:'small-button pdf-button',text:t('downloadPDF'),onclick:downloadPDF}),el('button',{type:'button',class:'small-button',text:t('print'),onclick:()=>window.print()})));}
function sectionTitle(key){return el('h3',{class:'report-section-title',text:t(key)});}
function caution(text,key='importantContext'){return el('aside',{class:'caution-card'},el('h4',{text:t(key)}),el('p',{text}));}
function table(headers,rows){const tbl=el('table');const head=el('thead',{},el('tr',{},headers.map(h=>el('th',{scope:'col',text:h}))));const body=el('tbody');for(const row of rows)body.append(el('tr',{},row.map(cell=>el('td',{},cell instanceof Node?cell:String(cell??'—')))));tbl.append(head,body);return el('div',{class:'table-wrap'},tbl);}
