function categoryName(value){if(categoryNames[value])return localized(categoryNames[value]);if(planets[value])return planetName(value);if(nakshatraEn.includes(value))return starName(value);if(signNames.en.includes(value))return signName(null,value);return value??'—';}
function renderMatch(container,data){if(!Array.isArray(data.kootas)||!Array.isArray(data.charts)){container.append(el('div',{class:'unavailable',text:t('resultUnavailable')}));return;}const score=Number(data.score),met=Boolean(data.threshold_met);const graph=el('div',{class:'score-graphic','aria-label':`${scoreValue(score)} / 36`});const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 150 150');svg.setAttribute('class','score-ring');svg.setAttribute('aria-hidden','true');for(const progress of [false,true]){const circle=document.createElementNS(ns,'circle');circle.setAttribute('cx','75');circle.setAttribute('cy','75');circle.setAttribute('r','65');circle.setAttribute('class',progress?'ring-progress':'ring-bg');if(progress){const total=2*Math.PI*65;circle.setAttribute('stroke-dasharray',String(total));circle.setAttribute('stroke-dashoffset',String(total*(1-Math.max(0,Math.min(36,score))/36)));}svg.append(circle);}graph.append(svg,el('div',{class:'score-number'},el('strong',{text:scoreValue(score)}),el('span',{text:t('outOf36')})));
container.append(el('div',{class:'card score-overview'},graph,el('div',{class:'score-text'},el('span',{class:'result-eyebrow',text:t('rawScore')}),el('h3',{text:t(met?'thresholdMet':'thresholdBelow')}),el('p',{text:t(met?'thresholdBody':'thresholdBelowBody')}),el('div',{class:'rule-badge'+(met?'':' warning'),text:`AK-1 · ${t('rawScore')}`}))));
container.append(sectionTitle('kootaDimensions'));const grid=el('div',{class:'koota-grid'});const symbols=['◈','⌁','✧','❧','☿','❋','☽','≋'];data.kootas.forEach((k,index)=>{const ratio=Math.max(0,Math.min(1,Number(k.score)/Number(k.max)));const details=el('details',{},el('summary',{text:t('scoreRule')}),el('p',{text:localized(kootaRules[k.key])}));grid.append(el('article',{class:'card koota-card'},el('div',{class:'koota-card-header'},el('span',{class:'koota-symbol','aria-hidden':'true',text:symbols[index]||'✧'}),el('span',{class:'koota-score'},el('strong',{text:scoreValue(k.score)}),` / ${k.max}`)),el('h4',{text:localized(kootaNames[k.key])||k.name}),el('p',{text:localized(kootaSubtitles[k.key])}),el('p',{style:'margin-top:8px',text:`${categoryName(k.value_a)} · ${categoryName(k.value_b)}`}),el('div',{class:'mini-progress','aria-hidden':'true'},el('span',{style:`width:${ratio*100}%`})),details));});container.append(grid,caution(t('contextBody')));container.append(el('p',{class:'result-disclaimer',text:t('matchRoles')}));if(data.charts.some(c=>c.profile?.time_accuracy==='approximate'))container.append(caution(t('accuracyCaution')));
container.append(sectionTitle('individualDetails'));const comparison=el('div',{class:'comparison-grid'});data.charts.forEach(chart=>comparison.append(profileSummary(chart)));container.append(comparison);for(const chart of data.charts){container.append(el('h3',{class:'report-name-label',text:chart.profile?.name||'—'}));renderManglikMini(container,chart);} }
