function renderChart(container,chart){if(!chart.planets||!chart.d1){container.append(el('div',{class:'unavailable',text:t('resultUnavailable')}));return;}container.append(profileSummary(chart));if(chart.profile?.time_accuracy==='approximate')container.append(caution(t('accuracyCaution')));container.append(sectionTitle('chartReport'));const chartGrid=el('div',{class:'chart-grid'});for(const [data,title]of [[chart.d1,'d1Title'],[chart.d9,'d9Title']]){const card=el('article',{class:'card chart-card'},el('h3',{text:t(title)}),el('p',{text:t('chartStyle')}));if(data)card.append(kundaliSvg(data));else card.append(el('p',{text:t('unavailable')}));card.append(el('p',{class:'d9-note',text:t(title==='d9Title'?'d9Caution':'chartLegend')}));chartGrid.append(card);}container.append(chartGrid);container.append(el('p',{class:'result-disclaimer',text:Object.entries(planetAbbr[state.lang]).map(([name,abbr])=>`${abbr} = ${planetName(name)}`).join(' · ')}));container.append(sectionTitle('planetPositions'));const rows=chart.planets.map(p=>[planetName(p.name),signName(p.sign_index,p.sign),`${fixed(p.longitude,4)}°`,String(p.house),signName(p.navamsa_sign_index,p.navamsa_sign),t(p.retrograde?'retrograde':'direct')]);container.append(table(['planet','sign','longitudeLabel','house','navamsa','motion'].map(t),rows));const birth=chart.birth||{};container.append(el('article',{class:'card summary-card',style:'margin-top:17px'},el('div',{class:'facts-grid'},fact('birthLocal',birth.local||'—'),fact('birthUTC',birth.utc||'—'),fact('ayanamsa',`${fixed(chart.ayanamsa_deg,6)}°`),fact('timezone',chart.profile?.timezone||'—'))));}
