function indiaToday(){try{const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const values=Object.fromEntries(parts.map(part=>[part.type,part.value]));return`${values.year}-${values.month}-${values.day}`;}catch(_){return today();}}
function readReviewRaw(){return{as_of:$('#review-as-of')?.value||'',horizon_months:$('#review-horizon-months')?.value||''};}
function renderReviewControls(previous=null){const old=previous||readReviewRaw(),box=$('#review-controls');box.replaceChildren(el('div',{class:'review-controls-heading'},el('h3',{text:t('reviewControls')}),el('p',{text:t('reviewControlsHelp')})));const grid=el('div',{class:'review-form-grid'});const date=field('review-as-of','reviewDate','date',{required:true,min:'1900-01-01',max:'2100-12-31',value:old.as_of||indiaToday()});const months=field('review-horizon-months','outlookMonths','number',{required:true,min:1,max:60,step:1,value:old.horizon_months||24,help:'outlookHelp'});date.input.addEventListener('input',invalidateResult);months.input.addEventListener('input',invalidateResult);grid.append(date.wrap,months.wrap);const relationship=selectField('relationship-status','relationshipStatus',[['considering','considering'],['married','alreadyMarried']],{value:old.relationship_status||'considering'});relationship.wrap.id='relationship-controls';relationship.input.addEventListener('change',invalidateResult);grid.append(relationship.wrap);box.append(grid);}
